function dashboard(){let debt=sum(db.sales,saleBalance);return `<div class="hero"><div><h2>🦁 SALIYA ENTERPRISES</h2><p>හවසට දවසේ ගනුදෙනු ඇතුළත් කරන්න. සේවක පඩි, ගල් වළ ගෙවීම් සහ Customer ණය ස්වයංක්‍රීයව ගණනය වෙනවා.</p></div></div><div class="stats">${stat('🔴','Customer ඉතිරි ණය',money(debt),true)}${stat('👷','සේවකයින්ට ගෙවිය යුතු ශේෂය',money(sum(db.employees,x=>Math.max(0,empBalance(x.id)))))}${stat('⛰️','ගල් වළවල්ට ගෙවිය යුතු ශේෂය',money(sum(db.quarries,x=>Math.max(0,quarryBalance(x.id)))))}${stat('🪨','අද Crusher Sales',money(sum(db.sales.filter(x=>x.date===today()),x=>x.cubes*x.price)))}</div><h2 class="sectionTitle">⚡ ඉක්මන් වැඩ (Quick Actions)</h2><div class="quick">${[['daily','🌇','හවස ගනුදෙනු'],['salary','📅','පඩි බලන්න'],['incoming','🚚','ගල් Loads'],['sales','🪨','Sales ඇතුළත්'],['credits','🔴','Customer ණය'],['quarrySettle','⛰️','ගල් වළ ගිණුම්']].map(x=>`<button onclick="show('${x[0]}')"><span>${x[1]}</span><b>${x[2]}</b><small class="muted">මෙතැන Click කරන්න →</small></button>`).join('')}</div><div class="stats">${stat('🚛','අද ගෙනා ගල් Cube',sum(db.loads.filter(x=>x.date===today()),x=>x.cubes).toFixed(2))}${stat('👷','අද වැඩ කළ සේවකයින්',new Set(db.work.filter(x=>x.date===today()).map(x=>x.employeeId)).size)}${stat('💸','අද සේවක ගෙවීම්',money(sum(db.empPay.filter(x=>x.date===today()),x=>x.amount)))}${stat('💳','අද ලැබුණු Sales මුදල්',money(sum(db.salePay.filter(x=>x.date===today()),x=>x.amount)))}</div><div class="help">ℹ️ <b>වැදගත්:</b> Customer ණය රතු පාටින් පෙන්වන්නේ සියලු Sales වලින් ලැබුණු මුදල් අඩු කළ පසු ඉතිරි ශේෂයයි. සේවකයෙක් වැඩ කළ මුදලට වඩා වැඩිපුර ගත්තොත් ඊළඟ පඩියෙන් අඩුවෙනවා.</div>`}
// Dashboard live summaries: derived from the same shared db state as transaction tables.
const dashboardBase=dashboard;
dashboard=function(){
 const todaysWork=db.work.filter(x=>x.date===today());
 const workRows=todaysWork.map(x=>`<tr><td>${safe(name(db.employees,x.employeeId))}</td><td>${money(x.wage)}</td><td>${safe(x.note||'—')}</td></tr>`);
 const recentSales=db.sales.slice().reverse().slice(0,8).map(x=>`<tr><td>${safe(x.date)}</td><td>${safe(name(db.customers,x.customerId))}</td><td>${money(num(x.cubes)*num(x.price))}</td><td>${money(saleBalance(x))}</td></tr>`);
 const employeeRows=db.employees.map(x=>`<tr><td>${safe(x.name)}</td><td>${money(empEarn(x.id))}</td><td>${money(empPaid(x.id))}</td><td>${money(empBalance(x.id))}</td></tr>`);
 return dashboardBase()+panel('👷 අද වැඩ කළ සේවකයින් ('+todaysWork.length+')',table(['සේවකයා','අද පඩිය','සටහන'],workRows))+
 panel('💵 සේවක වැටුප් සාරාංශය',table(['සේවකයා','උපයා ඇති මුදල','ගෙවූ මුදල','ඉතිරි ශේෂය'],employeeRows))+
 panel('🪨 අලුත්ම Sales Records',table(['දිනය','Customer','වටිනාකම','ඉතිරි ණය'],recentSales));
};
function daily(){return `<div class="hero"><div><h2>🌇 හවස වැඩ ඉක්මනින් ඇතුළත් කරන්න</h2><p>අද දිනය ස්වයංක්‍රීයව පුරවලා තියෙනවා. ඔබට අවශ්‍ය කොටස තෝරලා Save කරන්න.</p></div></div><div class="quick" style="margin-top:20px">${[['employees','👷','සේවක වැඩ'],['advances','💵','සේවක මුදල්'],['incoming','🚚','ගල් ගෙනා Loads'],['sales','🪨','Crusher Sales'],['quarryPay','💰','ගල් වළ ගෙවීම්'],['credits','🔴','Customer ණය ගෙවීම්']].map(x=>`<button onclick="show('${x[0]}')"><span>${x[1]}</span><b>${x[2]}</b><small>ඇතුළත් කරන්න →</small></button>`).join('')}</div>`}
function employees(){return panel('👷 අලුත් සේවකයෙක් එකතු කරන්න',`<div class="help">සේවකයාගේ නම එක වරක් Save කරන්න. ඉන්පසු දිනපතා වැඩ කළ පඩිය වෙනම ඇතුළත් කරන්න.</div><div class="form">${field('සේවකයාගේ නම *','empName')}${field('දුරකථන අංකය (අවශ්‍ය නම්)','empPhone','tel')}${select('සේවක අංශය','empSection',[{id:'Crusher',name:'Metal Crusher'},{id:'Block',name:'Block Production'},{id:'Transport',name:'Lorry / Transport'},{id:'Other',name:'Other'}])}${field('සාමාන්‍ය දිනක පඩිය (Rs.)','empDefault','number','0','min="0" step="0.01"')}</div>${formBtn('addEmployee','➕ සේවකයා එකතු කරන්න')}`)+panel('📅 අද වැඩ කළ විස්තර',`<div class="form">${field('වැඩ කළ දිනය','workDate','date',today())}${select('සේවකයා *','workEmp',db.employees)}${field('අදට අදාළ පඩිය (Rs.) *','workWage','number','','min="0" step="0.01"')}${field('සටහන (අවශ්‍ය නම්)','workNote')}</div>${formBtn('addWork','💾 අද වැඩ Save කරන්න')}<p class="muted mini">සේවකයා තෝරද්දී සාමාන්‍ය දිනක පඩිය Auto Fill වෙනවා. අවශ්‍ය නම් වෙනස් කරන්න.</p>`)+panel('📌 අද Save කළ වැඩ',table(['දිනය','සේවකයා','පඩිය','සටහන'],db.work.filter(x=>x.date===today()).map(x=>`<tr><td>${safe(x.date)}</td><td>${safe(name(db.employees,x.employeeId))}</td><td>${money(x.wage)}</td><td>${safe(x.note||'—')}</td></tr>`)))+panel('📋 සේවක ලැයිස්තුව',table(['නම','අංශය','සාමාන්‍ය පඩිය','උපයා ඇති මුදල','ගත් මුදල','ඉතිරි ශේෂය','ක්‍රියාව'],db.employees.map(x=>`<tr><td><b>${safe(x.name)}</b><br><small>${safe(x.phone)}</small></td><td>${safe(x.section)}</td><td>${money(x.defaultWage)}</td><td>${money(empEarn(x.id))}</td><td>${money(empPaid(x.id))}</td><td class="${empBalance(x.id)<0?'negative':'positive'}">${money(empBalance(x.id))}</td><td>${deleteButton('employees',x.id)}</td></tr>`)))+panel('🗂️ දිනපතා වැඩ කළ ඉතිහාසය',table(['දිනය','සේවකයා','පඩිය','සටහන','තත්ත්වය','ක්‍රියාව'],db.work.slice().reverse().map(x=>`<tr class="${db.empSettlements.some(s=>s.employeeId===x.employeeId&&inRange(x.date,s.from,s.to))?'settled':''}"><td>${x.date}</td><td>${safe(name(db.employees,x.employeeId))}</td><td>${money(x.wage)}</td><td>${safe(x.note)}</td><td>${db.empSettlements.some(s=>s.employeeId===x.employeeId&&inRange(x.date,s.from,s.to))?'<span class="pill paid">🟡 පඩි බැලූ දින</span>':'<span class="pill pending">Pending</span>'}</td><td>${deleteButton('work',x.id)}</td></tr>`)))}
function addEmployee(){if(!valid('empName'))return toast('සේවකයාගේ නම ඇතුළත් කරන්න');push('employees',{name:v('empName').trim(),phone:v('empPhone'),section:v('empSection'),defaultWage:amount('empDefault')})}function addWork(){if(!v('workEmp')||!v('workDate')||v('workWage')===''||amount('workWage')<0)return toast('දිනය, සේවකයා සහ පඩිය පුරවන්න');if(db.work.some(x=>x.date===v('workDate')&&x.employeeId===v('workEmp')))return toast('මේ සේවකයාගේ මේ දිනයේ වැඩ දැනටමත් තියෙනවා');push('work',{date:v('workDate'),employeeId:v('workEmp'),wage:amount('workWage'),note:v('workNote')})}
function advances(){return panel('💵 සේවකයා ඉල්ලූ මුදල් / Advance',`<div class="help">සේවකයෙක් හවසට සල්ලි ගත්තොත් මෙතැන Save කරන්න. ගත් මුදල පඩි ශේෂයෙන් ස්වයංක්‍රීයව අඩු වෙනවා.</div><div class="form">${field('දිනය','advDate','date',today())}${select('සේවකයා','advEmp',db.employees)}${field('දුන් මුදල (Rs.)','advAmount','number','','min="0.01" step="0.01"')}${field('සටහන','advNote')}</div>${formBtn('addAdvance','💾 මුදල් ගෙවීම Save කරන්න')}`)+panel('📒 සේවක ගෙවීම් ඉතිහාසය',table(['දිනය','සේවකයා','මුදල','වර්ගය','සටහන','ක්‍රියාව'],db.empPay.slice().reverse().map(x=>`<tr><td>${x.date}</td><td>${safe(name(db.employees,x.employeeId))}</td><td>${money(x.amount)}</td><td>${x.kind==='salary'?'පඩි පියවීම':'Advance / මුදල්'}</td><td>${safe(x.note)}</td><td>${deleteButton('empPay',x.id)}</td></tr>`)))}function addAdvance(){if(!v('advEmp')||amount('advAmount')<=0)return toast('සේවකයා සහ නිවැරදි මුදල ඇතුළත් කරන්න');push('empPay',{date:v('advDate'),employeeId:v('advEmp'),amount:amount('advAmount'),kind:'advance',note:v('advNote')})}
function salary(){const id=selectedEmp||db.employees[0]?.id||'';let rows=db.work.filter(x=>x.employeeId===id).sort((a,b)=>a.date.localeCompare(b.date));return panel('📅 කැමති දින පරාසයක පඩි බලන්න',`<div class="help">From / To තෝරන්න. පඩි ගණනයේදී කලින් ගත්ත සියලු මුදල් සහ ඉතිරි ණය ගණනයට ඇතුළත් වෙනවා. පඩි ගෙවූ දින 🟡 කහ පාටින් පෙන්වනවා.</div><div class="form">${select('සේවකයා','salaryEmp',db.employees,id)}${dates('sal')}</div><div class="actions"><button class="btn" onclick="calculateSalary()">🧮 පඩි ගණනය කරන්න</button></div><div id="salaryResult"></div>`)+panel('👷 සේවකයාගේ සම්පූර්ණ වැඩ ලැයිස්තුව',table(['දිනය','පඩිය','තත්ත්වය','ක්‍රියාව'],rows.map(x=>`<tr class="${db.empSettlements.some(s=>s.employeeId===id&&inRange(x.date,s.from,s.to))?'settled':''}"><td>${x.date}</td><td>${money(x.wage)}</td><td>${db.empSettlements.some(s=>s.employeeId===id&&inRange(x.date,s.from,s.to))?'🟡 පඩි බැලූ දිනය':'Pending'}</td><td>${deleteButton('work',x.id)}</td></tr>`)))+panel('🧾 කලින් පඩි බැලූ වාර්තා',table(['දින පරාසය','සේවකයා','ගණනය කළ පඩිය','එදා ගෙවූ මුදල','ක්‍රියාව'],db.empSettlements.slice().reverse().map(x=>`<tr><td>${x.from} → ${x.to}</td><td>${safe(name(db.employees,x.employeeId))}</td><td>${money(x.periodEarned)}</td><td>${money(x.paid)}</td><td>${deleteButton('empSettlements',x.id)}</td></tr>`)))}
function calculateSalary(){selectedEmp=v('salaryEmp');let id=selectedEmp,a=v('salFrom'),b=v('salTo');if(!id||!dateValid(a,b))return toast('සේවකයා සහ නිවැරදි දින පරාසය තෝරන්න');let w=db.work.filter(x=>x.employeeId===id&&inRange(x.date,a,b)),earned=sum(w,x=>x.wage),allEarn=sum(db.work.filter(x=>x.employeeId===id&&x.date<=b),x=>x.wage),allPaid=sum(db.empPay.filter(x=>x.employeeId===id&&x.date<=b),x=>x.amount),due=allEarn-allPaid;$('#salaryResult').innerHTML=`<div class="stats">${stat('📅','තෝරාගත් දින ගණන',w.length)}${stat('💰','එම දිනවල උපයා ඇති පඩිය',money(earned))}${stat('💵','${b} දක්වා ගත් මුළු මුදල',money(allPaid))}${stat('🧾','කලින් ණය ඇතුළුව ඉතිරි ශේෂය',money(due),due<0)}</div><div class="help">${due<0?`⚠️ සේවකයා ${money(-due)} වැඩිපුර ලබාගෙන තියෙනවා. මේ මුදල ඉදිරි පඩිවලින් අඩු වෙනවා.`:`දැනට ගෙවිය යුතු ශේෂය: <b>${money(due)}</b>`}<br>මෙය ${b} දක්වා සියලු වැඩ හා ගෙවීම් ඇතුළත් ශේෂයයි; තෝරාගත් දිනවල පඩිය වෙනම ඉහළ පෙන්වයි.</div><div class="form">${field('දැන් ගෙවන මුදල (Rs.)','salaryPay','number',Math.max(0,due),'min="0" step="0.01"')}${field('ගෙවූ දිනය','salaryPayDate','date',today())}</div><div class="actions"><button class="btn gold" onclick="settleSalary('${id}','${a}','${b}',${earned})">✅ පඩි ගෙවා දින Highlight කරන්න</button></div>`}
function settleSalary(id,a,b,earned){let p=amount('salaryPay');if(p<0||!Number.isFinite(p))return toast('මුදල නිවැරදි කරන්න');if(db.empSettlements.some(x=>x.employeeId===id&&x.from===a&&x.to===b))return toast('මේ දින පරාසය කලින් පියවා ඇත');db.empSettlements.push({id:uid(),employeeId:id,from:a,to:b,periodEarned:earned,paid:p,date:v('salaryPayDate')});if(p>0)db.empPay.push({id:uid(),employeeId:id,date:v('salaryPayDate'),amount:p,kind:'salary',note:`Salary period ${a} to ${b}`});save();toast('🟡 පඩි ගණනය සටහන් කළා')}
function quarries(){return panel('⛰️ ගල් වළක් එකතු කරන්න',`<div class="form">${field('ගල් වළේ / Supplier නම','qName')}${field('දුරකථන අංකය','qPhone','tel')}${field('කළුගල් Cube එකකට ගෙවන මිල (Rs.)','qRate','number',db.settings.cubeRate,'min="0" step="0.01"')}</div>${formBtn('addQuarry','➕ ගල් වළ Save කරන්න')}`)+panel('⛰️ ගල් වළ ලැයිස්තුව',table(['ගල් වළ','Cube මිල','මුළු Loads වටිනාකම','ගෙවූ මුදල','ඉතිරි ශේෂය','මිල වෙනස් කරන්න'],db.quarries.map(x=>`<tr><td><b>${safe(x.name)}</b></td><td>${money(x.rate)}</td><td>${money(quarryEarn(x.id))}</td><td>${money(quarryPaid(x.id))}</td><td class="${quarryBalance(x.id)<0?'negative':'positive'}">${money(quarryBalance(x.id))}</td><td>${deleteButton('quarries',x.id)}</td></tr>`)))}function addQuarry(){if(!valid('qName')||amount('qRate')<0)return toast('ගල් වළ නම සහ මිල ඇතුළත් කරන්න');push('quarries',{name:v('qName'),phone:v('qPhone'),rate:amount('qRate')})}function editQuarryRate(id){let q=byId(db.quarries,id),n=prompt('අලුත් Cube මිල (Rs.)',q.rate);if(n===null)return;if(n.trim()===''||!Number.isFinite(+n)||+n<0)return toast('වැරදි මිලක්');q.rate=+n;save();toast('අලුත් Loads වලට නව මිල යොදාගනී')}
function incoming(){return panel('🚚 අද ගල් වළෙන් ගෙනා කළුගල්',`<div class="help">ගල් වළ සහ Cube ගණන ඇතුළත් කළාම ගෙවිය යුතු මුදල ස්වයංක්‍රීයව ගණනය වෙනවා. කලින් Save කළ Loads වල මිල පසුව වෙනස් වෙන්නේ නැහැ.</div><div class="form">${field('දිනය','loadDate','date',today())}${select('ගල් වළ','loadQuarry',db.quarries)}${field('ගෙනා කළුගල් Cube ගණන','loadCubes','number','','min="0.01" step="0.01"')}${field('Lorry / රියදුරු (අවශ්‍ය නම්)','loadDriver')}</div><div id="loadPreview" class="help">ගල් වළ සහ Cube ගණන තෝරන්න.</div>${formBtn('addLoad','💾 ගල් Load Save කරන්න')}`)+panel('📋 ගල් ගෙනා Loads',table(['දිනය','ගල් වළ','Cube','Cube මිල','මුළු ගාස්තුව','රියදුරු','ක්‍රියාව'],db.loads.slice().reverse().map(x=>`<tr><td>${x.date}</td><td>${safe(name(db.quarries,x.quarryId))}</td><td>${x.cubes}</td><td>${money(x.rate)}</td><td>${money(x.cubes*x.rate)}</td><td>${safe(x.driver)}</td><td>${deleteButton('loads',x.id)}</td></tr>`)))}function addLoad(){let q=byId(db.quarries,v('loadQuarry'));if(!q||amount('loadCubes')<=0)return toast('ගල් වළ සහ Cube ගණන පුරවන්න');push('loads',{date:v('loadDate'),quarryId:q.id,cubes:amount('loadCubes'),rate:q.rate,driver:v('loadDriver')})}function previewLoad(){let q=byId(db.quarries,v('loadQuarry'));if($('#loadPreview'))$('#loadPreview').innerHTML=q?`Cube මිල: <b>${money(q.rate)}</b> × ${amount('loadCubes')} Cube = <b>${money(q.rate*amount('loadCubes'))}</b>`:'මුලින් ගල් වළක් එකතු කරන්න'}
function quarryPay(){return panel('💰 ගල් වළට දුන් මුදල් / Advance',`<div class="form">${field('දිනය','qpDate','date',today())}${select('ගල් වළ','qpQuarry',db.quarries)}${field('ගෙවූ මුදල (Rs.)','qpAmount','number','','min="0.01" step="0.01"')}${field('සටහන','qpNote')}</div>${formBtn('addQuarryPayment','💾 ගෙවීම Save කරන්න')}`)+panel('📒 ගල් වළ ගෙවීම් ඉතිහාසය',table(['දිනය','ගල් වළ','මුදල','සටහන','ක්‍රියාව'],db.quarryPay.slice().reverse().map(x=>`<tr><td>${x.date}</td><td>${safe(name(db.quarries,x.quarryId))}</td><td>${money(x.amount)}</td><td>${safe(x.note)}</td><td>${deleteButton('quarryPay',x.id)}</td></tr>`)))}function addQuarryPayment(){if(!v('qpQuarry')||amount('qpAmount')<=0)return toast('ගල් වළ සහ ගෙවූ මුදල පුරවන්න');push('quarryPay',{date:v('qpDate'),quarryId:v('qpQuarry'),amount:amount('qpAmount'),note:v('qpNote')})}
function quarrySettle(){return panel('⛰️ ගල් වළ ගිණුම් – Date Range',`<div class="help">From / To දීලා ඒ දිනවල ගෙනා Cube, වටිනාකම සහ ගෙවූ මුදල් බලන්න. කලින් වැඩිපුර ගෙවූ මුදල් ඊළඟ ගණනයට අඩු වෙනවා.</div><div class="form">${select('ගල් වළ','qsQuarry',db.quarries,selectedQuarry||db.quarries[0]?.id)}${dates('qs')}</div><div class="actions"><button class="btn" onclick="calculateQuarry()">🧮 ගිණුම ගණනය කරන්න</button></div><div id="quarryResult"></div>`)+panel('🗂️ ගල් වළ පියවීම් ඉතිහාසය',table(['ගල් වළ','දින පරාසය','Cube','වටිනාකම','පියවූ ශේෂය','පියවීමෙන් පසු ඉතිරිය'],db.quarrySettlements.slice().reverse().map(x=>`<tr><td>${safe(name(db.quarries,x.quarryId))}</td><td>${x.from} → ${x.to}</td><td>${x.cubes}</td><td>${money(x.value)}</td><td>${money(x.paid)}</td></tr>`)))}function calculateQuarry(){selectedQuarry=v('qsQuarry');let id=selectedQuarry,a=v('qsFrom'),b=v('qsTo');if(!id||!dateValid(a,b))return toast('ගල් වළ සහ දින පරාසය තෝරන්න');let loads=db.loads.filter(x=>x.quarryId===id&&inRange(x.date,a,b)),cubes=sum(loads,x=>x.cubes),value=sum(loads,x=>x.cubes*x.rate),allEarn=sum(db.loads.filter(x=>x.quarryId===id&&x.date<=b),x=>x.cubes*x.rate),allPaid=sum(db.quarryPay.filter(x=>x.quarryId===id&&x.date<=b),x=>x.amount),due=allEarn-allPaid;$('#quarryResult').innerHTML=`<div class="stats">${stat('🚛','තෝරාගත් Cube',cubes.toFixed(2))}${stat('💰','එම දිනවල වටිනාකම',money(value))}${stat('💵',b+' දක්වා ගෙවූ මුදල',money(allPaid))}${stat('🧾','පෙර ශේෂය ඇතුළුව ගෙවිය යුතු මුදල',money(due),due<0)}</div><div class="help">${due<0?'ගල් වළට වැඩිපුර ගෙවූ '+money(-due)+' ඉදිරි ගිණුම්වලින් අඩුවේ.':'ගෙවිය යුතු මුළු ශේෂය '+money(due)}. මේක ${b} දක්වා සියලු Loads සහ ගෙවීම් ඇතුළත් ශේෂයයි.</div><div class="form">${field('පියවූ ශේෂය – දැන් ගෙවන මුදල (Rs.)','qsPay','number',Math.max(0,due),'min="0" step="0.01"')}${field('ගෙවූ දිනය','qsPayDate','date',today())}</div><div id="qsBalancePreview" class="help"></div><div class="actions"><button class="btn gold" onclick="settleQuarry('${id}','${a}','${b}',${cubes},${value})">✅ ගිණුම පියවා Save කරන්න</button></div>${table(['දිනය','Cube','මිල','මුළු මුදල'],loads.map(x=>`<tr class="${db.quarrySettlements.some(s=>s.quarryId===id&&inRange(x.date,s.from,s.to))?'settled':''}"><td>${x.date}</td><td>${x.cubes}</td><td>${money(x.rate)}</td><td>${money(x.cubes*x.rate)}</td></tr>`))}`}
function previewQuarryBalance(){let el=$('#qsBalancePreview');if(!el)return;let id=v('qsQuarry'),b=v('qsTo'),due=sum(db.loads.filter(x=>x.quarryId===id&&x.date<=b),x=>x.cubes*x.rate)-sum(db.quarryPay.filter(x=>x.quarryId===id&&x.date<=b),x=>x.amount),raw=v('qsPay'),p=raw===''?0:Number(raw);if(!Number.isFinite(p)||p<0){el.textContent='⚠️ නිවැරදි ගෙවීම් මුදලක් ඇතුළත් කරන්න';return}let remaining=due-p;el.innerHTML=`<b>💰 ගෙවිය යුතු ශේෂය:</b> ${money(due)} &nbsp; | &nbsp; <b>✅ පියවූ ශේෂය:</b> ${money(p)} &nbsp; | &nbsp; <b style="color:${remaining>0?'#b91c1c':'#047857'}">${remaining<0?'වැඩිපුර ගෙවූ මුදල':'තව ගෙවීමට ඇති ශේෂය'}: ${money(Math.abs(remaining))}</b><br><small>ඉතිරි මුදල ඊළඟ ගිණුම් ගණනයට ස්වයංක්‍රීයව ගෙනයනු ලැබේ.</small>`}
function settleQuarry(id,a,b,cubes,value){if(db.quarrySettlements.some(x=>x.quarryId===id&&x.from===a&&x.to===b))return toast('මේ දින පරාසය කලින් සටහන් කර ඇත. ඉතිරි මුදල පසුව ගෙවීමට ගල් වළ ගෙවීම් පිටුව භාවිතා කරන්න');let raw=v('qsPay'),p=Number(raw);if(raw===''||!Number.isFinite(p)||p<0)return toast('නිවැරදි පියවූ මුදලක් ඇතුළත් කරන්න');let date=v('qsPayDate');if(!date)return toast('ගෙවූ දිනය තෝරන්න');let due=quarryBalance(id);let remainingAfter=due-p;db.quarrySettlements.push({id:uid(),quarryId:id,from:a,to:b,cubes,value,paid:p,date,remainingAfter});if(p>0)db.quarryPay.push({id:uid(),date,quarryId:id,amount:p,note:`Partial/full settlement ${a} to ${b}`});save();toast('⏳ Firebase Save තහවුරු කරමින්...')}
function sales(){return panel('👤 අලුත් Customer එකතු කරන්න',`<div class="form">${field('Customer නම','customerName')}${field('Phone Number','customerPhone','tel')}</div>${formBtn('addCustomer','➕ Customer Save කරන්න')}`)+panel('🪨 Crusher එකෙන් ගිය Load එකක් ඇතුළත් කරන්න',`<div class="help">Full Payment, Partial Payment හෝ Credit වශයෙන් Sale එක Save කරන්න. ඉතිරි මුදල Customer ණය පොතට Auto Update වෙනවා.</div><div class="form three">${field('දිනය','saleDate','date',today())}${select('Customer නම','saleCustomer',db.customers)}${select('ගල් වර්ගය','saleProduct',['Gal Kudu','Chips','Kalavan','3/4 Metal','Other'].map(x=>({id:x,name:x})))}${field('Cube ගණන','saleCubes','number','','min="0.01" step="0.01"')}${field('Cube එකක මිල (Rs.)','salePrice','number','','min="0" step="0.01"')}${field('දැන් ලැබුණු මුදල (Rs.)','saleReceived','number','0','min="0" step="0.01"')}</div><div id="salePreview" class="help">Cube ගණන සහ මිල ඇතුළත් කරන්න.</div>${formBtn('addSale','💾 Sale එක Save කරන්න')}`)+panel('📋 ගිය Loads / Sales',table(['දිනය','Customer','වර්ගය','Cube','මුළු වටිනාකම','ලැබුණු මුදල','ඉතිරි ණය','ක්‍රියාව'],db.sales.slice().reverse().map(x=>`<tr><td>${x.date}</td><td>${safe(name(db.customers,x.customerId))}</td><td>${safe(x.product)}</td><td>${x.cubes}</td><td>${money(x.cubes*x.price)}</td><td>${money(salePaid(x.id))}</td><td class="${saleBalance(x)>0?'negative':'positive'}">${money(saleBalance(x))}</td><td>${deleteButton('sales',x.id)}</td></tr>`)))}function addCustomer(){if(!valid('customerName'))return toast('Customer නම ඇතුළත් කරන්න');push('customers',{name:v('customerName'),phone:v('customerPhone')})}function previewSale(){if($('#salePreview')){let total=amount('saleCubes')*amount('salePrice'),paid=amount('saleReceived');$('#salePreview').innerHTML=`මුළු වටිනාකම: <b>${money(total)}</b> | ලැබුණු මුදල: <b>${money(paid)}</b> | <span class="negative">ඉතිරි ණය: ${money(total-paid)}</span>`}}function addSale(){let total=amount('saleCubes')*amount('salePrice'),paid=amount('saleReceived');if(!v('saleCustomer')||amount('saleCubes')<=0||amount('salePrice')<0||paid<0||paid>total)return toast('Customer, Cube, මිල සහ ලැබුණු මුදල නිවැරදි කරන්න');let id=uid();db.sales.push({id,date:v('saleDate'),customerId:v('saleCustomer'),product:v('saleProduct'),cubes:amount('saleCubes'),price:amount('salePrice')});if(paid>0)db.salePay.push({id:uid(),saleId:id,date:v('saleDate'),amount:paid});save();toast('Sale එක සහ ණය ශේෂය Save වුණා')}
function blockSales(){
 const blocks=db.sales.filter(x=>x.product==='Concrete බ්ලොක් ගණන');
 return `<div class="hero"><div><h2>🧱 බ්ලොක් ගල් විකුණුම්</h2><p>Customer ගෙනගිය බ්ලොක් ගල් ගණන, එකක මිල සහ ලැබුණු මුදල ඇතුළත් කරන්න. ඉතිරි ණය Customer ණය පොතට ස්වයංක්‍රීයව එකතු වේ.</p></div></div>`+
 panel('👤 අලුත් Customer කෙනෙක් එකතු කරන්න',`<div class="form">${field('Customer නම','customerName')}${field('දුරකථන අංකය','customerPhone','tel')}</div>${formBtn('addCustomer','➕ Customer Save කරන්න')}`)+
 panel('🧱 අලුත් බ්ලොක් ගල් විකිණීම',`<div class="help">සම්පූර්ණ මුදල, කොටසක් හෝ ණයට නම් Rs. 0 ඇතුළත් කරන්න. ඉතිරි ණය ස්වයංක්‍රීයව ගණනය වේ.</div><div class="form three">${field('දිනය','blockDate','date',today())}${select('Customer','blockCustomer',db.customers)}${field('බ්ලොක් ගල් ගණන','blockQty','number','','min="1" step="1"')}${field('බ්ලොක් එකක මිල (Rs.)','blockPrice','number','','min="0.01" step="0.01"')}${field('දැන් ලැබුණු මුදල (Rs.)','blockReceived','number','0','min="0" step="0.01"')}</div><div id="blockPreview" class="help">ගල් ගණන සහ මිල ඇතුළත් කළ විට එකතුව පෙන්වයි.</div>${formBtn('addBlockSale','💾 බ්ලොක් විකිණීම Save කරන්න')}`)+
 `<div class="stats">${stat('🧱','විකුණූ බ්ලොක් ගණන',sum(blocks,x=>x.cubes).toLocaleString('en-LK'))}${stat('💵','මුළු බ්ලොක් විකුණුම්',money(sum(blocks,x=>x.cubes*x.price)))}${stat('🔴','බ්ලොක් ණය ශේෂය',money(sum(blocks,saleBalance)),true)}</div>`+
 panel('📋 බ්ලොක් විකුණුම් ඉතිහාසය',table(['දිනය','Customer','බ්ලොක් ගණන','එකක මිල','මුළු මුදල','ලැබුණු මුදල','ඉතිරි ණය','ක්‍රියාව'],blocks.slice().reverse().map(x=>`<tr><td>${safe(x.date)}</td><td>${safe(name(db.customers,x.customerId))}</td><td>${x.cubes}</td><td>${money(x.price)}</td><td>${money(x.cubes*x.price)}</td><td>${money(salePaid(x.id))}</td><td class="${saleBalance(x)>0.005?'negative':'positive'}">${money(saleBalance(x))}</td><td>${deleteButton('sales',x.id)}</td></tr>`)))+
 `<div class="actions"><button class="btn" onclick="show('credits')">🔴 Customer ණය පොත බලන්න →</button></div>`;
}
function previewBlockSale(){let el=$('#blockPreview');if(!el)return;let total=amount('blockQty')*amount('blockPrice'),paid=amount('blockReceived');el.innerHTML=`මුළු මුදල: <b>${money(total)}</b> &nbsp; | &nbsp; ලැබුණු මුදල: <b>${money(paid)}</b> &nbsp; | &nbsp; <span class="negative">ඉතිරි ණය: <b>${money(Math.max(0,total-paid))}</b></span>`}
function addBlockSale(){
 const qty=amount('blockQty'),price=amount('blockPrice'),paid=amount('blockReceived'),date=v('blockDate'),customerId=v('blockCustomer');
 const total=qty*price;
 if(!customerId||!byId(db.customers,customerId))return toast('මුලින් Customer කෙනෙක් එකතු කර තෝරන්න');
 if(!date||!Number.isInteger(qty)||qty<=0||!Number.isFinite(price)||price<=0||!Number.isFinite(paid)||paid<0||paid>total+0.001)return toast('දිනය, බ්ලොක් ගණන, මිල සහ ලැබුණු මුදල පරීක්ෂා කරන්න');
 const id=uid();
 db.sales.push({id,date,customerId,product:'Concrete බ්ලොක් ගණන',cubes:qty,price});
 if(paid>0)db.salePay.push({id:uid(),saleId:id,date,amount:paid});
 save();toast('⏳ Firebase Save තහවුරු කරමින්...');
}

function credits(){
 let due=db.customers.map(x=>({...x,balance:customerBalance(x.id)}));
 let groups=[];let seen=new Set();
 for(const x of db.salePay.slice().reverse()){
  const key=x.paymentGroup||x.id;if(seen.has(key))continue;seen.add(key);
  const parts=db.salePay.filter(p=>(p.paymentGroup||p.id)===key);
  const sale=byId(db.sales,x.saleId);const cid=x.customerId||sale?.customerId||parts.map(p=>byId(db.sales,p.saleId)?.customerId).find(Boolean);
  groups.push({id:key,date:x.date,customerId:cid,amount:sum(parts,p=>p.amount),count:parts.length});
 }
 return `<div class="stats">${stat('🔴','සියලු Customer ණය එකතුව',money(sum(db.sales,saleBalance)),true)}${stat('👤','ණය ඇති Customers',due.filter(x=>x.balance>0.005).length)}${stat('🪨','මුළු Sales වටිනාකම',money(sum(db.sales,x=>x.cubes*x.price)))}${stat('💵','මුළු ලැබුණු මුදල',money(sum(db.salePay,x=>x.amount)))}</div>`+
 panel('🔴 Customer අනුව ණය',table(['Customer','Phone','මුළු ඉතිරි ණය','විස්තර'],due.map(x=>`<tr><td><b>${safe(x.name)}</b></td><td>${safe(x.phone)}</td><td class="${x.balance>0?'negative':'positive'}">${money(x.balance)}</td><td><button class="btn light" onclick="selectedCustomer='${x.id}';render()">බලන්න</button></td></tr>`)))+
 panel('💵 Customer ණය ගෙවීම',`<div class="help">Customer තෝරලා ලැබුණු මුදල ඇතුළත් කරන්න. Load එක තෝරන්න අවශ්‍ය නැහැ. පරණම ඉතිරි ණයෙන් පටන්ගෙන මුදල ස්වයංක්‍රීයව අඩු වෙනවා.</div><div class="form">${select('Customer','creditCustomer',db.customers,selectedCustomer||db.customers[0]?.id)}${field('ලැබුණු මුදල (Rs.)','creditAmount','number','','min="0.01" step="0.01"')}${field('ගෙවූ දිනය','creditDate','date',today())}</div><div id="creditPreview" class="help"></div>${formBtn('receiveCredit','💾 ණය ගෙවීම Save කරන්න')}`)+
 panel('📒 Customer ගෙවීම් ඉතිහාසය',table(['දිනය','Customer','ලැබුණු මුදල','සටහන','ක්‍රියාව'],groups.map(x=>`<tr><td>${safe(x.date)}</td><td>${safe(name(db.customers,x.customerId))}</td><td>${money(x.amount)}</td><td>${x.count>1?'Loads '+x.count+'කට බෙදා ඇත':'Payment'}</td><td>${deleteButton('salePay',x.id)}</td></tr>`)));
}
function populateCredit(){previewCredit()}
function previewCredit(){const el=$('#creditPreview');if(!el)return;const cid=v('creditCustomer'),balance=customerBalance(cid),a=amount('creditAmount');el.innerHTML=`Customerගේ මුළු ඉතිරි ණය: <b class="negative">${money(balance)}</b> | ගෙවූ පසු ඉතිරි: <b>${money(Math.max(0,balance-a))}</b>`}
function receiveCredit(){const cid=v('creditCustomer'),a=amount('creditAmount'),date=v('creditDate');if(!cid||!date||!Number.isFinite(a)||a<=0||a>customerBalance(cid)+0.005)return toast('Customer සහ ඉතිරි ණයට නොවැඩි මුදලක් ඇතුළත් කරන්න');let remain=Math.round(a*100),group=uid();let sales=db.sales.filter(x=>x.customerId===cid&&saleBalance(x)>0.005).sort((a,b)=>a.date.localeCompare(b.date));for(const sale of sales){if(remain<=0)break;let take=Math.min(remain,Math.round(saleBalance(sale)*100));if(take<=0)continue;db.salePay.push({id:uid(),saleId:sale.id,customerId:cid,paymentGroup:group,date,amount:take/100});remain-=take}if(remain>0)return toast('ගෙවීම ගණනය කිරීමේ ගැටලුවක්');selectedCustomer=cid;save();toast('✅ Customerගේ ණය මුදල අඩු කළා')}

const recordTypes=[['employees','👷 සේවක ලැයිස්තුව'],['work','👷 දෛනික වැඩ'],['empPay','💵 සේවක ගෙවීම්'],['empSettlements','📅 පඩි පියවීම්'],['loads','🚚 ගල් Loads'],['quarryPay','⛰️ ගල් වළ ගෙවීම්'],['quarrySettlements','🧾 ගල් වළ පියවීම්'],['sales','🪨 Crusher / Block Sales'],['salePay','💳 Customer ගෙවීම්']];
function deleteButton(type,id){return `<button type="button" class="btn light record-delete" onclick="deleteRecord('${type}','${safe(id)}')">🗑️ Delete</button>`}
function deleteRecord(type,id){if(!recordTypes.some(x=>x[0]===type))return;if(type==='employees'){const linked=db.work.some(x=>x.employeeId===id)||db.empPay.some(x=>x.employeeId===id)||db.empSettlements.some(x=>x.employeeId===id);if(linked){alert('⚠️ මෙම සේවකයාට අදාළ වැඩ, පඩි හෝ ගෙවීම් Records තියෙනවා. ගිණුම් ආරක්ෂා කිරීමට සේවකයා Delete කළ නොහැක. වැරදි Records මුලින් පරීක්ෂා කරන්න.');return}}let matches=type==='salePay'?db.salePay.filter(x=>(x.paymentGroup||x.id)===id):db[type].filter(x=>x.id===id);if(!matches.length)return toast('Record එක හමු වුණේ නැහැ');let detail=type==='sales'?'මෙම Sale එකට අදාළ ගෙවීම් ද මැකෙනවා.':type==='empSettlements'?'මෙම පඩි පියවීම සමඟ සම්බන්ධ ගෙවීමක් තිබුණොත් එයත් මැකෙනවා.':type==='quarrySettlements'?'මෙම පියවීමට අදාළ ගෙවීමක් තිබුණොත් එයත් මැකෙනවා.':'';if(!confirm('⚠️ මෙම Record එක Delete කරන්නද? '+detail+'\nමෙය ආපසු Undo කළ නොහැක. මුලින් Backup එකක් ගන්න.'))return;
 if(type==='sales'){let ids=new Set(matches.map(x=>x.id));db.salePay=db.salePay.filter(x=>!ids.has(x.saleId))}
 if(type==='empSettlements'){for(let x of matches){db.empPay=db.empPay.filter(p=>!(p.employeeId===x.employeeId&&p.kind==='salary'&&p.date===x.date&&p.note===`Salary period ${x.from} to ${x.to}`))}}
 if(type==='quarrySettlements'){for(let x of matches){if(x.paymentId)db.quarryPay=db.quarryPay.filter(p=>p.id!==x.paymentId)}}
 if(type==='salePay')db.salePay=db.salePay.filter(x=>(x.paymentGroup||x.id)!==id);else db[type]=db[type].filter(x=>x.id!==id);
 save();toast('🗑️ Record එක Delete කළා');}
function recordDescription(type,x){switch(type){case 'employees':return safe(x.name)+' – '+safe(x.section);case 'work':return name(db.employees,x.employeeId)+' – '+money(x.wage);case 'empPay':return name(db.employees,x.employeeId)+' – '+money(x.amount);case 'empSettlements':return name(db.employees,x.employeeId)+' – '+x.from+' සිට '+x.to;case 'loads':return name(db.quarries,x.quarryId)+' – '+x.cubes+' Cube';case 'quarryPay':return name(db.quarries,x.quarryId)+' – '+money(x.amount);case 'quarrySettlements':return name(db.quarries,x.quarryId)+' – '+(x.from||'')+' සිට '+(x.to||'');case 'sales':return name(db.customers,x.customerId)+' – '+safe(x.product)+' – '+money(x.cubes*x.price);case 'salePay':return name(db.customers,x.customerId||byId(db.sales,x.saleId)?.customerId)+' – '+money(x.amount);default:return ''}}
function records(){return `<div class="hero"><div><h2>🗑️ වැරදි ගනුදෙනු Delete කරන්න</h2><p>එක Record එකක් පමණක් මකන්න. Delete කිරීමට පෙර Backup JSON එකක් ගන්න.</p></div></div><div class="actions"><button class="btn" onclick="backup()">⬇ මුලින් Backup ගන්න</button></div>`+recordTypes.map(([type,title])=>{let arr=db[type]||[];if(type==='salePay'){let seen=new Set();arr=arr.filter(x=>{let k=x.paymentGroup||x.id;if(seen.has(k))return false;seen.add(k);return true})}return panel(title,table(['දිනය','විස්තරය','ක්‍රියාව'],arr.slice().reverse().map(x=>`<tr><td>${safe(x.date||x.from||'—')}</td><td>${recordDescription(type,x)}</td><td>${deleteButton(type,type==='salePay'?(x.paymentGroup||x.id):x.id)}</td></tr>`))) }).join('')}
function reports(){return panel('📊 සම්පූර්ණ ගිණුම් සාරාංශය',`<div class="stats">${stat('🪨','Sales එකතුව',money(sum(db.sales,x=>x.cubes*x.price)))}${stat('🔴','ඉතිරි Customer ණය',money(sum(db.sales,saleBalance)),true)}${stat('👷','සේවක පඩි එකතුව',money(sum(db.work,x=>x.wage)))}${stat('⛰️','ගල් වළ ගාස්තු එකතුව',money(sum(db.loads,x=>x.cubes*x.rate)))}</div><div class="actions"><button class="btn" onclick="window.print()">🖨️ Print Report</button><button class="btn light" onclick="backup()">⬇ Full Data Backup</button><button class="btn light" onclick="exportCSV()">⬇ Sales CSV</button></div><p class="muted">මෙය ලැබීම්, ගෙවීම් සහ ශේෂ සාරාංශයකි. සියලු වියදම් ඇතුළත් නොවන නිසා Net Profit එකක් නොවේ.</p>`)+panel('📅 දින අනුව විස්තර',`<div class="form">${dates('report')}</div><div class="actions"><button class="btn" onclick="calcReport()">🔎 Report බලන්න</button></div><div id="reportResult"></div>`)}function calcReport(){let a=v('reportFrom'),b=v('reportTo');if(!dateValid(a,b))return toast('දින පරාසය නිවැරදි කරන්න');let w=db.work.filter(x=>inRange(x.date,a,b)),l=db.loads.filter(x=>inRange(x.date,a,b)),s=db.sales.filter(x=>inRange(x.date,a,b)),p=db.salePay.filter(x=>inRange(x.date,a,b));$('#reportResult').innerHTML=`<div class="stats">${stat('👷','වැඩ කළ දින Records',w.length)}${stat('💵','එම දිනවල පඩි',money(sum(w,x=>x.wage)))}${stat('🚚','ගෙනා ගල් Cube',sum(l,x=>x.cubes).toFixed(2))}${stat('🪨','Sales වටිනාකම',money(sum(s,x=>x.cubes*x.price)))}</div>${table(['දිනය','Customer','වර්ගය','Cube','වටිනාකම'],s.map(x=>`<tr><td>${x.date}</td><td>${safe(name(db.customers,x.customerId))}</td><td>${safe(x.product)}</td><td>${x.cubes}</td><td>${money(x.cubes*x.price)}</td></tr>`))}<p>මේ කාලය තුළ ලැබුණු Sales Payments: <b>${money(sum(p,x=>x.amount))}</b></p>`}
function settings(){return `<div class="actions"><button class="btn red" onclick="show('records')">🗑️ වැරදි Records Delete කරන්න</button></div>`+panel('⚙️ Default ගල් Cube මිල',`<div class="help">අලුත් ගල් වළක් එකතු කරන විට මෙහි මිල Auto Fill වෙනවා. ගල් වළට වෙනම මිලක් තිබුණොත් එතැන වෙනස් කරන්න පුළුවන්.</div><div class="form">${field('Default කළුගල් Cube මිල (Rs.)','defaultCube','number',db.settings.cubeRate,'min="0" step="0.01"')}</div>${formBtn('saveSettings','💾 Settings Save කරන්න')}`)+panel('🔐 දත්ත ආරක්ෂාව',`<p>Firebase Save තහවුරු වූ දත්ත Cloud එකේ පවතී. නිතර JSON Backup එකක් ගන්න.</p><div class="actions"><button class="btn" onclick="backup()">⬇ Backup JSON</button></div><p class="negative">Firebase connection status එක sidebar එකෙන් පරීක්ෂා කරන්න.</p>`)+`<section class="panel danger-zone"><h2>🗑️ සියලු දත්ත Clear කරන්න</h2><div class="help">⚠️ මේ Browser එකේ Save කළ සේවකයින්, පඩි, ගල් වළ, Loads, Sales, Customer ණය සහ Settings සියල්ල මැකෙනවා. මෙය ආපසු Undo කළ නොහැක. මුලින් Backup JSON එකක් Download කරගන්න.</div><div class="field"><label for="clearPassword">Clear කිරීමේ Password එක</label><input id="clearPassword" type="password" placeholder="Password ඇතුළත් කරන්න" autocomplete="off"></div><div class="actions"><button class="btn light" onclick="backup()">⬇ මුලින් Backup ගන්න</button><button class="btn red" onclick="clearAllBusinessData()">🗑️ සියලු දත්ත Clear කරන්න</button></div><p class="mini muted">මෙම Password එක Demo එකේ වැරදිව දත්ත මැකීම වැළැක්වීමට පමණයි; සැබෑ Login Security එකක් නොවේ.</p></section>`}function saveSettings(){if(amount('defaultCube')<0)return toast('නිවැරදි මිලක් දෙන්න');db.settings.cubeRate=amount('defaultCube');save();toast('Settings Save වුණා')}
function clearAllBusinessData(){const el=$('#clearPassword');if(!el||el.value!=='123'){if(el)el.value='';return toast('❌ Password එක වැරදියි')}if(!confirm('⚠️ සියලු ව්‍යාපාර දත්ත සම්පූර්ණයෙන්ම මකන්නද? Backup එකක් ගත් බව තහවුරු කරන්න.'))return;if(!confirm('අවසාන තහවුරු කිරීම: සියලු Records සහ Settings මකා දමන්නද?'))return;localStorage.removeItem(KEY);db=structuredClone(initial);selectedEmp='';selectedQuarry='';selectedCustomer='';page='dashboard';render();toast('✅ මේ Browser එකේ සියලු Business Data Clear කළා')}
function backup(){let blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Saliya_Backup_'+today()+'.json';a.click();URL.revokeObjectURL(a.href)}function restore(ev){let f=ev.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let d=JSON.parse(r.result);if(!Array.isArray(d.employees)||!Array.isArray(d.sales))throw Error();if(!confirm('දැනට තිබෙන දත්ත වෙනුවට Backup දත්ත Restore කරන්නද?'))return;db={...structuredClone(initial),...d};save();toast('Backup Restore වුණා')}catch{toast('Backup file එක නිවැරදි නැහැ')}};r.readAsText(f)}function exportCSV(){let lines=[['Date','Customer','Product','Cubes','Price per cube','Total','Received','Balance'],...db.sales.map(x=>[x.date,name(db.customers,x.customerId),x.product,x.cubes,x.price,x.cubes*x.price,salePaid(x.id),saleBalance(x)])];let csv='\ufeff'+lines.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='Saliya_Sales_'+today()+'.csv';a.click();URL.revokeObjectURL(a.href)}
document.addEventListener('change',e=>{if(e.target.id==='workEmp'){let emp=byId(db.employees,v('workEmp'));if($('#workWage'))$('#workWage').value=emp?.defaultWage||0}if(['loadQuarry','loadCubes'].includes(e.target.id))previewLoad();if(['saleCubes','salePrice','saleReceived'].includes(e.target.id))previewSale();if(e.target.id==='creditCustomer')populateCredit();if(e.target.id==='creditSale')previewCredit();if(e.target.id==='salaryEmp'){selectedEmp=v('salaryEmp');render()}if(e.target.id==='qsQuarry'){selectedQuarry=v('qsQuarry');render()}});document.addEventListener('input',e=>{if(e.target.id==='creditAmount')previewCredit();if(e.target.id==='qsPay')previewQuarryBalance();if(['loadCubes'].includes(e.target.id))previewLoad();if(['saleCubes','salePrice','saleReceived'].includes(e.target.id))previewSale()});const oldRender=render;render=function(){oldRender();if(page==='employees'&&$('#workEmp')){let emp=byId(db.employees,v('workEmp'));$('#workWage').value=emp?.defaultWage||0}if(page==='incoming')previewLoad();if(page==='credits')populateCredit();if(page==='sales')previewSale();mountStatusCalendar()};render();

// Custom business calendar: browser-native date pickers cannot show per-day colors.
let businessCalendarMonth=today().slice(0,7);
function businessCalendarData(date){
 const emp=selectedEmp||db.employees[0]?.id;
 const paidSalary=db.empSettlements.some(x=>x.employeeId===emp&&inRange(date,x.from,x.to));
 const worked=db.work.some(x=>x.employeeId===emp&&x.date===date);
 const creditSales=db.sales.filter(x=>x.date===date&&saleBalance(x)>0.005);
 const totalCredit=sum(creditSales,saleBalance);
 return {paidSalary,worked,creditSales,totalCredit};
}
function mountStatusCalendar(){
 if(!['salary','sales','credits'].includes(page))return;
 const target=$('#content');if(!target)return;
 let wrap=document.createElement('section');wrap.className='panel status-calendar-panel';wrap.id='statusCalendarPanel';
 // Keep the range calculation controls first; calendar is a second, clearly visible panel.
 const first=target.querySelector('.panel');if(page==='salary'&&first)first.after(wrap);else target.prepend(wrap);
 drawStatusCalendar();
}
function changeBusinessCalendarMonth(delta){
 const [y,m]=businessCalendarMonth.split('-').map(Number);const d=new Date(y,m-1+delta,1);
 businessCalendarMonth=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');drawStatusCalendar();
}
function jumpBusinessCalendarToday(){businessCalendarMonth=today().slice(0,7);drawStatusCalendar()}
function drawStatusCalendar(){
 const el=$('#statusCalendarPanel');if(!el)return;
 const [year,month]=businessCalendarMonth.split('-').map(Number);
 const first=new Date(year,month-1,1).getDay(),days=new Date(year,month,0).getDate();
 const title=new Date(year,month-1,1).toLocaleString('en-US',{month:'long',year:'numeric'});
 const salaryMode=page==='salary';
 let cells=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div class="biz-cal-week">${x}</div>`).join('');
 for(let i=0;i<first;i++)cells+='<div class="biz-cal-empty"></div>';
 for(let day=1;day<=days;day++){
  const date=businessCalendarMonth+'-'+String(day).padStart(2,'0');const info=businessCalendarData(date);
  const classes=['biz-cal-day'];let badges=[];
  if(salaryMode){if(info.paidSalary){classes.push('biz-cal-paid');badges.push('Paid')}else if(info.worked){classes.push('biz-cal-worked');badges.push('Worked')}}
  else if(info.totalCredit>0.005){classes.push('biz-cal-credit');badges.push('Credit')}
  if(date===today())classes.push('biz-cal-today');
  const selected=salaryMode&&[v('salFrom'),v('salTo')].includes(date);
  if(selected)classes.push('biz-cal-selected');
  cells+=`<button type="button" class="${classes.join(' ')}" onclick="chooseBusinessCalendarDate('${date}')" title="${date}${info.totalCredit>0?' • Outstanding '+money(info.totalCredit):''}"><b>${day}</b>${badges.map(x=>`<small>${x}</small>`).join('')}</button>`;
 }
 el.innerHTML=`<div class="biz-cal-heading"><div><h2>📅 ${salaryMode?'Salary Payment Calendar':'Customer Credit Calendar'}</h2><p class="muted mini">${salaryMode?'Yellow = salary period recorded. Blue = worked, not settled.':'Red = a load from this day still has unpaid customer credit.'}</p></div><div class="biz-cal-controls"><button type="button" class="btn light" onclick="changeBusinessCalendarMonth(-1)">❮</button><strong>${title}</strong><button type="button" class="btn light" onclick="changeBusinessCalendarMonth(1)">❯</button><button type="button" class="btn light" onclick="jumpBusinessCalendarToday()">Today</button></div></div><div class="biz-cal-grid">${cells}</div><div class="biz-cal-legend">${salaryMode?'<span><i class="legend-yellow"></i> Salary recorded</span><span><i class="legend-blue"></i> Worked</span>':'<span><i class="legend-red"></i> Unpaid credit load</span>'}<span><i class="legend-outline"></i> Today</span></div><p class="muted mini">${salaryMode?'Click a date to set From, then click another date to set To. Use Calculate Salary to view totals.':'Click a red date to see the unpaid loads and balances for that day.'}</p><div id="businessCalendarDetails"></div>`;
}
let calendarRangeNext='from';
function chooseBusinessCalendarDate(date){
 if(page==='salary'){
  const from=$('#salFrom'),to=$('#salTo');if(!from||!to)return;
  if(calendarRangeNext==='from'){from.value=date;to.value=date;calendarRangeNext='to'}
  else {if(date<from.value){to.value=from.value;from.value=date}else to.value=date;calendarRangeNext='from'}
  drawStatusCalendar();return;
 }
 const matches=db.sales.filter(x=>x.date===date&&saleBalance(x)>0.005);
 const details=$('#businessCalendarDetails');if(!details)return;
 details.innerHTML=`<div class="biz-cal-detail"><h3>🔴 Credit Loads – ${date}</h3>${matches.length?table(['Customer','Product','Cubes','Total','Received','Balance'],matches.map(x=>`<tr><td>${safe(name(db.customers,x.customerId))}</td><td>${safe(x.product)}</td><td>${x.cubes}</td><td>${money(x.cubes*x.price)}</td><td>${money(salePaid(x.id))}</td><td class="negative"><b>${money(saleBalance(x))}</b></td></tr>`)):'<p>No unpaid credit loads for this day.</p>'}</div>`;
}

// Colored calendar directly attached to the From/To fields (not the separate calendar panel).
let activeRangePicker=null,rangePickerMonth='';
function openRangeCalendar(id){
 const input=document.getElementById(id);if(!input)return;
 if(activeRangePicker===id){closeRangeCalendar();return}
 closeRangeCalendar();activeRangePicker=id;rangePickerMonth=(input.value||today()).slice(0,7);
 const holder=input.closest('.range-date-field');
 const pop=document.createElement('div');pop.className='range-calendar-pop';pop.id='rangeCalendarPop';holder.appendChild(pop);
 renderRangeCalendar();
}
function closeRangeCalendar(){document.getElementById('rangeCalendarPop')?.remove();activeRangePicker=null}
function moveRangeCalendar(months){const [y,m]=rangePickerMonth.split('-').map(Number);const d=new Date(y,m-1+months,1);rangePickerMonth=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;renderRangeCalendar()}
function rangeCalendarFlags(date){
 if(activeRangePicker?.startsWith('sal')){
  const id=v('salaryEmp')||selectedEmp||db.employees[0]?.id;
  return {paid:db.empSettlements.some(x=>x.employeeId===id&&inRange(date,x.from,x.to)),worked:db.work.some(x=>x.employeeId===id&&x.date===date)};
 }
 if(activeRangePicker?.startsWith('qs')){
  const id=v('qsQuarry')||selectedQuarry||db.quarries[0]?.id;
  return {paid:db.quarrySettlements.some(x=>x.quarryId===id&&inRange(date,x.from,x.to)),worked:db.loads.some(x=>x.quarryId===id&&x.date===date)};
 }
 return {paid:false,worked:false};
}
function renderRangeCalendar(){
 const pop=document.getElementById('rangeCalendarPop');if(!pop||!activeRangePicker)return;
 const [y,m]=rangePickerMonth.split('-').map(Number),first=new Date(y,m-1,1).getDay(),days=new Date(y,m,0).getDate();
 const monthTitle=new Date(y,m-1,1).toLocaleDateString('en-US',{month:'long',year:'numeric'});
 let grid=['Su','Mo','Tu','We','Th','Fr','Sa'].map(x=>`<span class="range-weekday">${x}</span>`).join('');
 for(let i=0;i<first;i++)grid+='<span></span>';
 for(let day=1;day<=days;day++){
  const date=rangePickerMonth+'-'+String(day).padStart(2,'0'),flags=rangeCalendarFlags(date);
  const credit=db.sales.some(x=>x.date===date&&saleBalance(x)>0.005);
  const cls=['range-day',flags.paid?'range-day-paid':flags.worked?'range-day-worked':'',credit?'range-day-credit':'',date===v(activeRangePicker)?'range-day-selected':''].join(' ');
  grid+=`<button type="button" class="${cls}" title="${date}${flags.paid?' - Salary/settlement recorded':''}${credit?' - Customer credit load':''}" onclick="chooseRangeCalendarDay('${date}')">${day}${credit?'<i class="credit-dot"></i>':''}</button>`;
 }
 pop.innerHTML=`<div class="range-cal-header"><button type="button" onclick="moveRangeCalendar(-1)" aria-label="Previous month">❮</button><strong>${monthTitle}</strong><button type="button" onclick="moveRangeCalendar(1)" aria-label="Next month">❯</button></div><div class="range-cal-grid">${grid}</div><div class="range-cal-legend"><span><i class="range-key yellow"></i> පඩි / පියවූ දින</span><span><i class="range-key blue"></i> වැඩ / Loads</span><span><i class="range-key red"></i> ණය Load</span></div><button type="button" class="range-cal-today" onclick="chooseRangeCalendarDay(today())">Today</button>`;
}
function chooseRangeCalendarDay(date){
 const input=document.getElementById(activeRangePicker);if(!input)return;
 input.value=date;input.dispatchEvent(new Event('change',{bubbles:true}));closeRangeCalendar();
 if(typeof drawStatusCalendar==='function')drawStatusCalendar();
}
document.addEventListener('click',e=>{if(activeRangePicker&&!e.target.closest('.range-date-field'))closeRangeCalendar()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeRangeCalendar()});

document.addEventListener('input',e=>{if(['blockQty','blockPrice','blockReceived'].includes(e.target.id))previewBlockSale()});
document.addEventListener('change',e=>{if(['blockQty','blockPrice','blockReceived'].includes(e.target.id))previewBlockSale()});
const _saliyaBlockRender=render;render=function(){_saliyaBlockRender();if(page==='blockSales')previewBlockSale()};


/* 2026-11-22: Safe inline Edit and Delete actions. */
const editFields={
 employees:[['name','සේවක නම','text'],['phone','Phone','text'],['section','අංශය','text'],['defaultWage','සාමාන්‍ය පඩිය','number']],
 quarries:[['name','ගල් වළ නම','text'],['phone','Phone','text'],['rate','Cube මිල','number']],
 customers:[['name','Customer නම','text'],['phone','Phone','text']],
 work:[['date','දිනය','date'],['wage','පඩිය','number'],['note','සටහන','text']],
 empPay:[['date','දිනය','date'],['amount','ගෙවූ මුදල','number'],['note','සටහන','text']],
 empSettlements:[['date','පියවූ දිනය','date'],['from','සිට','date'],['to','දක්වා','date']],
 loads:[['date','දිනය','date'],['cubes','Cube','number'],['rate','Cube මිල','number']],
 quarryPay:[['date','දිනය','date'],['amount','ගෙවූ මුදල','number'],['note','සටහන','text']],
 quarrySettlements:[['date','පියවූ දිනය','date'],['from','සිට','date'],['to','දක්වා','date']],
 sales:[['date','දිනය','date'],['product','වර්ගය','text'],['cubes','Cube / බ්ලොක් ගණන','number'],['price','එකක මිල','number']],
 salePay:[['date','දිනය','date'],['amount','ලැබුණු මුළු මුදල','number']]
};
const oldDeleteButton=deleteButton;
deleteButton=function(type,id){return `<span class="row-actions"><button type="button" class="btn light edit-action" onclick="editRecord('${type}','${safe(id)}')">✏️ Edit</button>${oldDeleteButton(type,id)}</span>`};
function editRecord(type,id){
 if(!editFields[type])return toast('Edit කිරීම සඳහා මේ Record වර්ගය සකස් කර නැහැ');
 const group=type==='salePay'?db.salePay.filter(x=>(x.paymentGroup||x.id)===id):[];
 const record=type==='salePay'?group[0]:byId(db[type]||[],id);
 if(!record)return toast('Record එක හමු වුණේ නැහැ');
 document.getElementById('saliyaEditOverlay')?.remove();
 const fields=editFields[type];
 const content=fields.map(([key,label,kind])=>{
  const value=type==='salePay'&&key==='amount'?sum(group,x=>x.amount):record[key]??'';
  return `<label class="edit-field"><b>${label}</b><input data-edit-key="${key}" type="${kind}" value="${safe(value)}" ${kind==='number'?'min="0" step="any"':''}></label>`;
 }).join('');
 const overlay=document.createElement('div');overlay.id='saliyaEditOverlay';overlay.className='saliya-edit-overlay';
 overlay.innerHTML=`<div class="saliya-edit-dialog" role="dialog" aria-modal="true" aria-label="Edit record"><h2>✏️ ගනුදෙනුව Edit කරන්න</h2><p>Save කළ පසු අදාළ ශේෂ ස්වයංක්‍රීයව වෙනස් වෙනවා.</p><div class="saliya-edit-grid">${content}</div><div class="actions"><button class="btn light" onclick="closeRecordEditor()">Cancel</button><button class="btn gold" onclick="saveRecordEdit('${type}','${safe(id)}')">💾 Save Changes</button></div></div>`;
 document.body.appendChild(overlay);
 overlay.addEventListener('click',e=>{if(e.target===overlay)closeRecordEditor()});
}
function closeRecordEditor(){document.getElementById('saliyaEditOverlay')?.remove()}
function saveRecordEdit(type,id){
 const target=type==='salePay'?db.salePay.find(x=>(x.paymentGroup||x.id)===id):byId(db[type]||[],id);
 if(!target)return toast('Record එක හමු වුණේ නැහැ');
 const data={...target};
 for(const [key,label,kind] of editFields[type]){
  const el=document.querySelector('#saliyaEditOverlay [data-edit-key="'+key+'"]');if(!el)return;
  const raw=el.value.trim();
  if(kind==='number'){
   if(raw===''||!Number.isFinite(Number(raw))||Number(raw)<0)return alert(label+' නිවැරදි කරන්න');
   data[key]=Number(raw);
  }else{if(kind==='date'&&!raw)return alert(label+' තෝරන්න');data[key]=raw}
 }
 if(['employees','customers','quarries'].includes(type)&&!data.name.trim())return alert('නම ඇතුළත් කරන්න');
 if(['sales','loads'].includes(type)&&(data.cubes<=0||data.price===0&&type==='sales'||data.rate===0&&type==='loads'))return alert('Cube සහ මිල 0 ට වැඩි විය යුතුයි');
 if(['empSettlements','quarrySettlements'].includes(type)&&data.from>data.to)return alert('From / To දිනය නිවැරදි කරන්න');
 if(type==='work'&&db.work.some(x=>x.id!==id&&x.employeeId===data.employeeId&&x.date===data.date))return alert('මේ සේවකයාගේ එම දිනයේ වැඩ දැනටමත් ඇත');
 if(type==='sales'&&data.cubes*data.price+0.005<salePaid(id))return alert('Sale එකේ දැනට ලැබුණු මුදලට වඩා අඩු මුළු වටිනාකමක් Save කරන්න බැහැ. මුලින් Payment එක නිවැරදි කරන්න.');
 if(type==='salePay'){
  const oldGroup=db.salePay.filter(x=>(x.paymentGroup||x.id)===id);
  const customerId=oldGroup[0].customerId||byId(db.sales,oldGroup[0].saleId)?.customerId;
  if(!customerId)return alert('Customer සොයාගන්න බැහැ');
  const without=db.salePay.filter(x=>(x.paymentGroup||x.id)!==id);
  const salesFor=db.sales.filter(x=>x.customerId===customerId).sort((a,b)=>a.date.localeCompare(b.date));
  const available=sum(salesFor,x=>Math.max(0,x.cubes*x.price-sum(without.filter(p=>p.saleId===x.id),p=>p.amount)));
  if(data.amount>available+0.005)return alert('Customerගේ ඉතිරි ණයට වඩා වැඩි මුදලක් Save කරන්න බැහැ');
  let cents=Math.round(data.amount*100);const replacement=[];
  for(const sale of salesFor){if(cents<=0)break;const free=Math.max(0,Math.round((sale.cubes*sale.price-sum(without.filter(p=>p.saleId===sale.id),p=>p.amount))*100));const take=Math.min(cents,free);if(take>0){replacement.push({id:uid(),saleId:sale.id,customerId,paymentGroup:id,date:data.date,amount:take/100});cents-=take}}
  if(cents>0)return alert('Payment එක බෙදීම අසාර්ථකයි');
  db.salePay=[...without,...replacement];
 }else{
  if(type==='empSettlements'){
   const pay=db.empPay.find(p=>p.employeeId===target.employeeId&&p.kind==='salary'&&p.date===target.date&&p.note===`Salary period ${target.from} to ${target.to}`);
   if(pay){pay.date=data.date;pay.note=`Salary period ${data.from} to ${data.to}`}
  }
  if(type==='quarrySettlements'&&target.paymentId){const pay=byId(db.quarryPay,target.paymentId);if(pay)pay.date=data.date}
  Object.assign(target,data);
 }
 closeRecordEditor();save();toast('✅ Record එක Update කළා');
}
// Keep master records editable in the Records screen, while blocking unsafe deletion of linked masters.
recordTypes.push(['quarries','⛰️ ගල් වළ නම් / Cube මිල'],['customers','👤 Customer නම්']);
const previousDeleteRecord=deleteRecord;
deleteRecord=function(type,id){
 if(type==='quarries'&&(db.loads.some(x=>x.quarryId===id)||db.quarryPay.some(x=>x.quarryId===id)||db.quarrySettlements.some(x=>x.quarryId===id)))return alert('මේ ගල් වළට අදාළ Loads / Payments තියෙන නිසා Delete කරන්න බැහැ. Edit කරන්න පුළුවන්.');
 if(type==='customers'&&db.sales.some(x=>x.customerId===id))return alert('මේ Customerට Sales තියෙන නිසා Delete කරන්න බැහැ. Edit කරන්න පුළුවන්.');
 return previousDeleteRecord(type,id)
};
